DECLARE parent_name TEXT := managed::text; fallback TEXT := managed::text || '_default';
    col TEXT := CASE managed WHEN 'execution_history' THEN 'time' ELSE 'created' END;
    leaf TEXT; hi TIMESTAMPTZ; found_rows BIGINT; owner_name TEXT; registered RECORD;
    v_origin xid8 := pg_current_xact_id(); v_xmin xid := v_origin::xid;
BEGIN
    IF row_cap <= 0 OR row_cap = 9223372036854775807 OR NOT isfinite(day)
       OR day <> date_trunc('day', day, 'UTC') THEN
        RAISE EXCEPTION 'Expected finite UTC day and positive bounded repair cap' USING ERRCODE = '22023';
    END IF;
    hi := day + interval '24 hours';
    leaf := parent_name || '_p' || to_char(day AT TIME ZONE 'UTC', 'YYYYMMDD');
    EXECUTE format('LOCK TABLE ONLY %I IN ACCESS EXCLUSIVE MODE', parent_name);
    EXECUTE format('LOCK TABLE ONLY %I IN ACCESS EXCLUSIVE MODE', fallback);
    PERFORM native_partition_check(managed, fallback, NULL, NULL, true);
    SELECT * INTO registered FROM native_partition_registry WHERE parent = managed AND lower_bound = day;
    IF FOUND THEN
        IF registered.partition_name <> leaf OR registered.upper_bound <> hi THEN
            RAISE EXCEPTION 'Incompatible native registry entry: %', leaf USING ERRCODE = '55000';
        END IF;
        PERFORM native_partition_check(managed, leaf, day, hi);
        RETURN QUERY SELECT 'already_present'::text, 0::bigint;
        RETURN;
    END IF;
    IF to_regclass(leaf) IS NOT NULL THEN
        RAISE EXCEPTION 'Refusing unregistered native relation: %', leaf USING ERRCODE = '55000';
    END IF;
    EXECUTE format('SELECT count(*) FROM (SELECT 1 FROM ONLY %I WHERE %I >= $1 AND %I < $2 LIMIT $3) bounded', fallback, col, col)
        INTO found_rows USING day, hi, row_cap + 1;
    IF found_rows > row_cap THEN
        RETURN QUERY SELECT 'deferred_over_budget'::text, found_rows;
        RETURN;
    END IF;
    EXECUTE format('CREATE TABLE %I (LIKE %I INCLUDING ALL)', leaf, parent_name);
    SELECT pg_get_userbyid(relowner) INTO owner_name FROM pg_class WHERE oid = to_regclass(parent_name);
    EXECUTE format('ALTER TABLE %I OWNER TO %I', leaf, owner_name);
    EXECUTE format('ALTER TABLE %I ADD CONSTRAINT native_day_bound CHECK (%I >= %L::timestamptz AND %I < %L::timestamptz)', leaf, col, day, col, hi);
    EXECUTE format('WITH moved AS (DELETE FROM ONLY %I WHERE %I >= $1 AND %I < $2 RETURNING *) INSERT INTO %I SELECT * FROM moved', fallback, col, col, leaf)
        USING day, hi;
    GET DIAGNOSTICS rows_moved = ROW_COUNT;
    -- Whole remaining DEFAULT validation is still deadline-bound. Any timeout
    -- rolls back the move and the newly created destination together.
    EXECUTE format('ALTER TABLE %I ADD CONSTRAINT native_default_exclusion CHECK (NOT (%I >= %L::timestamptz AND %I < %L::timestamptz)) NOT VALID', fallback, col, day, col, hi);
    EXECUTE format('ALTER TABLE %I VALIDATE CONSTRAINT native_default_exclusion', fallback);
    EXECUTE format('ALTER TABLE %I ATTACH PARTITION %I FOR VALUES FROM (%L) TO (%L)', parent_name, leaf, day, hi);
    EXECUTE format('ALTER TABLE %I DROP CONSTRAINT native_default_exclusion', fallback);
    INSERT INTO native_partition_registry(parent, partition_name, lower_bound, upper_bound) VALUES (managed, leaf, day, hi);
    PERFORM native_partition_check(managed, leaf, day, hi);
    -- Physical moves bypass the parent statement triggers. Invalidate only
    -- affected source predicates, once per kind/hour, in this same transaction.
    IF rows_moved > 0 AND managed = 'event' THEN
        EXECUTE format('INSERT INTO native_summary_invalidation(kind,bucket)
            SELECT ''event_volume'',bucket FROM (SELECT DISTINCT date_trunc(''hour'',created,''UTC'') AS bucket FROM %I) affected
            WHERE NOT EXISTS (SELECT 1 FROM native_summary_invalidation existing
                WHERE existing.kind=''event_volume'' AND existing.bucket=affected.bucket
                AND existing.transaction_origin=$1 AND existing.xmin=$2)', leaf) USING v_origin,v_xmin;
    ELSIF rows_moved > 0 AND managed = 'execution_history' THEN
        EXECUTE format('INSERT INTO native_summary_invalidation(kind,bucket)
            SELECT ''execution_status'',bucket FROM (SELECT DISTINCT date_trunc(''hour'',time,''UTC'') AS bucket FROM %I WHERE ''status''=ANY(changed_fields)) affected
            WHERE NOT EXISTS (SELECT 1 FROM native_summary_invalidation existing
                WHERE existing.kind=''execution_status'' AND existing.bucket=affected.bucket
                AND existing.transaction_origin=$1 AND existing.xmin=$2)', leaf) USING v_origin,v_xmin;
        EXECUTE format('INSERT INTO native_summary_invalidation(kind,bucket)
            SELECT ''execution_creation'',bucket FROM (SELECT DISTINCT date_trunc(''hour'',time,''UTC'') AS bucket FROM %I WHERE operation=''INSERT'') affected
            WHERE NOT EXISTS (SELECT 1 FROM native_summary_invalidation existing
                WHERE existing.kind=''execution_creation'' AND existing.bucket=affected.bucket
                AND existing.transaction_origin=$1 AND existing.xmin=$2)', leaf) USING v_origin,v_xmin;
    END IF;
    RETURN QUERY SELECT 'applied'::text, rows_moved;
END

DECLARE r native_partition_registry; summary_kind native_summary_kind; summary_name TEXT;
BEGIN
    EXECUTE format('LOCK TABLE ONLY %I IN ACCESS EXCLUSIVE MODE', managed::text);
    SELECT * INTO r FROM native_partition_registry WHERE id = registry_id AND parent = managed FOR UPDATE;
    IF NOT FOUND THEN RETURN false; END IF;
    IF r.upper_bound > cutoff THEN RETURN false; END IF;
    IF r.partition_name <> managed::text || '_p' || to_char(r.lower_bound AT TIME ZONE 'UTC', 'YYYYMMDD') THEN
        RAISE EXCEPTION 'Incompatible native expiry name: %', r.partition_name USING ERRCODE = '55000';
    END IF;
    PERFORM native_partition_check(managed, r.partition_name, r.lower_bound, r.upper_bound);
    FOR summary_kind IN SELECT k FROM unnest(CASE managed
        WHEN 'event' THEN ARRAY['event_volume'::native_summary_kind]
        WHEN 'execution_history' THEN ARRAY['execution_status'::native_summary_kind, 'execution_creation'::native_summary_kind]
        ELSE ARRAY[]::native_summary_kind[] END) k ORDER BY k LOOP
        PERFORM 1 FROM native_summary_state WHERE native_summary_state.kind = summary_kind FOR UPDATE;
        summary_name := CASE summary_kind WHEN 'event_volume' THEN 'event_volume_hourly_summary'
            WHEN 'execution_status' THEN 'execution_status_hourly_summary' ELSE 'execution_creation_hourly_summary' END;
        EXECUTE format('DELETE FROM %I WHERE bucket >= $1 AND bucket < $2', summary_name) USING r.lower_bound, r.upper_bound;
        DELETE FROM native_summary_hour h WHERE h.kind = summary_kind AND h.bucket >= r.lower_bound AND h.bucket < r.upper_bound;
        DELETE FROM native_summary_invalidation n WHERE n.kind = summary_kind AND n.bucket >= r.lower_bound AND n.bucket < r.upper_bound;
    END LOOP;
    EXECUTE format('DROP TABLE %I', r.partition_name);
    DELETE FROM native_partition_registry WHERE id = r.id;
    RETURN true;
END

DECLARE
    parent_schema TEXT;
    parent_owner TEXT;
    child_name TEXT := cache_generation_partition_name(generation_id);
    child_relation TEXT;
BEGIN
    -- Caller holds admission and SHARE UPDATE EXCLUSIVE parent protection.
    SELECT n.nspname, pg_get_userbyid(c.relowner) INTO STRICT parent_schema, parent_owner
      FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
     WHERE c.oid = 'cache_entry'::REGCLASS AND c.relkind = 'p';
    child_relation := format('%I.%I', parent_schema, child_name);
    INSERT INTO cache_owner_physical_byte_usage(owner_type, owner, physical_bytes)
        SELECT n.owner_type, n.owner, 0 FROM cache_generation g
        JOIN cache_namespace n ON n.id = g.namespace WHERE g.id = generation_id
        ON CONFLICT (owner_type, owner) DO NOTHING;
    INSERT INTO cache_generation_entry_usage(generation) VALUES (generation_id);
    EXECUTE format('CREATE TABLE %s (LIKE cache_entry INCLUDING DEFAULTS INCLUDING CONSTRAINTS)', child_relation);
    EXECUTE format('ALTER TABLE %s ADD CHECK (generation = %s)', child_relation, generation_id);
    EXECUTE format('ALTER TABLE cache_entry ATTACH PARTITION %s FOR VALUES IN (%s)', child_relation, generation_id);
    -- Distinct API and supervisor logins may inherit the same owner role.
    -- Leaving the leaf owned by the API login would prevent supervisor DROP.
    EXECUTE format('ALTER TABLE %s OWNER TO %I', child_relation, parent_owner);
    PERFORM validate_cache_generation_partition(generation_id);
    UPDATE cache_entry_statistics_state SET partitions_created = partitions_created + 1 WHERE id = TRUE;
    IF NOT FOUND THEN RAISE EXCEPTION 'cache statistics state is missing'; END IF;
END;

DECLARE
    namespace_id BIGINT;
    namespace_row cache_namespace%ROWTYPE;
    generation_row cache_generation%ROWTYPE;
    usage_row cache_generation_entry_usage%ROWTYPE;
    child_relation TEXT;
BEGIN
    IF traversal_seconds < 0 OR traversal_seconds IS NULL THEN
        RAISE EXCEPTION 'cache traversal window must be nonnegative';
    END IF;
    PERFORM pg_advisory_xact_lock(7821101, 0);
    LOCK TABLE ONLY cache_entry IN ACCESS EXCLUSIVE MODE;
    SELECT namespace INTO namespace_id FROM cache_generation WHERE id = generation_id;
    IF NOT FOUND THEN
        RETURN QUERY SELECT 'absent'::TEXT, 0::BIGINT, 0::BIGINT;
        RETURN;
    END IF;
    SELECT * INTO STRICT namespace_row FROM cache_namespace WHERE id = namespace_id FOR UPDATE;
    SELECT * INTO STRICT generation_row FROM cache_generation WHERE id = generation_id FOR UPDATE;
    IF namespace_row.active_generation IS NOT DISTINCT FROM generation_id
       OR NOT COALESCE(generation_row.state = 'failed' OR (
            generation_row.state = 'retired'
            AND generation_row.readable_until <= clock_timestamp()
            AND generation_row.retired <= clock_timestamp() - make_interval(secs => traversal_seconds::DOUBLE PRECISION)
       ), FALSE)
       OR EXISTS (
            SELECT 1 FROM workflow_cache_iteration i JOIN workflow_execution w ON w.id = i.workflow_execution
             WHERE i.generation = generation_id AND i.state = 'scanning'
               AND w.status NOT IN ('completed', 'failed', 'cancelled', 'timeout', 'abandoned')
       ) THEN
        RETURN QUERY SELECT 'ineligible'::TEXT, 0::BIGINT, 0::BIGINT;
        RETURN;
    END IF;
    child_relation := validate_cache_generation_partition(generation_id);
    PERFORM 1 FROM cache_deployment_physical_byte_usage WHERE id = 1 FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'cache deployment usage is missing'; END IF;
    PERFORM 1 FROM cache_owner_physical_byte_usage
      WHERE owner_type = namespace_row.owner_type AND owner = namespace_row.owner FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'cache owner usage is missing'; END IF;
    SELECT * INTO STRICT usage_row FROM cache_generation_entry_usage WHERE generation = generation_id FOR UPDATE;
    EXECUTE format('DROP TABLE %s', child_relation);
    UPDATE cache_deployment_physical_byte_usage
       SET physical_bytes = physical_bytes - usage_row.physical_bytes
     WHERE id = 1 AND physical_bytes >= usage_row.physical_bytes;
    IF NOT FOUND THEN RAISE EXCEPTION 'cache deployment usage underflow'; END IF;
    UPDATE cache_owner_physical_byte_usage
       SET physical_bytes = physical_bytes - usage_row.physical_bytes
     WHERE owner_type = namespace_row.owner_type AND owner = namespace_row.owner
       AND physical_bytes >= usage_row.physical_bytes;
    IF NOT FOUND THEN RAISE EXCEPTION 'cache owner usage underflow'; END IF;
    DELETE FROM cache_generation_entry_usage WHERE generation = generation_id;
    DELETE FROM cache_ingest_chunk WHERE generation = generation_id;
    DELETE FROM cache_generation WHERE id = generation_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'cache generation disappeared during reclamation'; END IF;
    UPDATE cache_entry_statistics_state SET partitions_dropped = partitions_dropped + 1 WHERE id = TRUE;
    IF NOT FOUND THEN RAISE EXCEPTION 'cache statistics state is missing'; END IF;
    RETURN QUERY SELECT 'dropped'::TEXT, usage_row.record_count, usage_row.physical_bytes;
END;

DECLARE r native_partition_registry; summary_kind native_summary_kind; summary_name TEXT;
BEGIN
    PERFORM file_evidence_gc_entry();
    EXECUTE format('LOCK TABLE ONLY %I IN ACCESS EXCLUSIVE MODE',managed::text);
    SELECT id,parent,partition_name,lower_bound,upper_bound,created INTO r FROM native_partition_registry WHERE id=registry_id AND parent=managed FOR UPDATE;
    IF NOT FOUND OR r.upper_bound>cutoff THEN RETURN false; END IF;
    IF managed='event' AND EXISTS(SELECT 1 FROM file_evidence_pin WHERE kind='event' AND source_created>=r.lower_bound AND source_created<r.upper_bound) THEN RETURN false; END IF;
    IF r.partition_name<>managed::text || '_p' || to_char(r.lower_bound AT TIME ZONE 'UTC','YYYYMMDD') THEN
        RAISE EXCEPTION 'Incompatible native expiry name: %',r.partition_name USING ERRCODE='55000';
    END IF;
    PERFORM native_partition_check(managed,r.partition_name,r.lower_bound,r.upper_bound);
    FOR summary_kind IN SELECT k FROM unnest(CASE managed
      WHEN 'event' THEN ARRAY['event_volume'::native_summary_kind]
      WHEN 'execution_history' THEN ARRAY['execution_status'::native_summary_kind,'execution_creation'::native_summary_kind]
      ELSE ARRAY[]::native_summary_kind[] END) k ORDER BY k LOOP
        PERFORM 1 FROM native_summary_state WHERE native_summary_state.kind=summary_kind FOR UPDATE;
        summary_name:=CASE summary_kind WHEN 'event_volume' THEN 'event_volume_hourly_summary'
          WHEN 'execution_status' THEN 'execution_status_hourly_summary' ELSE 'execution_creation_hourly_summary' END;
        EXECUTE format('DELETE FROM %I WHERE bucket>=$1 AND bucket<$2',summary_name) USING r.lower_bound,r.upper_bound;
        DELETE FROM native_summary_hour h WHERE h.kind=summary_kind AND h.bucket>=r.lower_bound AND h.bucket<r.upper_bound;
        DELETE FROM native_summary_invalidation n WHERE n.kind=summary_kind AND n.bucket>=r.lower_bound AND n.bucket<r.upper_bound;
    END LOOP;
    EXECUTE format('DROP TABLE %I',r.partition_name);
    DELETE FROM native_partition_registry WHERE id=r.id;
    RETURN true;
END;

DECLARE
    namespace_id BIGINT;
    namespace_row cache_namespace%ROWTYPE;
    generation_row cache_generation%ROWTYPE;
    usage_row cache_generation_entry_usage%ROWTYPE;
    child_relation TEXT;
BEGIN
    IF traversal_seconds < 0 OR traversal_seconds IS NULL THEN RAISE EXCEPTION 'cache traversal window must be nonnegative'; END IF;
    PERFORM file_evidence_gc_entry();
    IF file_evidence_cache_generation_pinned(generation_id) THEN
        RETURN QUERY SELECT 'ineligible'::TEXT,0::BIGINT,0::BIGINT; RETURN;
    END IF;
    PERFORM pg_advisory_xact_lock(7821101,0);
    LOCK TABLE ONLY cache_entry IN ACCESS EXCLUSIVE MODE;
    SELECT namespace INTO namespace_id FROM cache_generation WHERE id=generation_id;
    IF NOT FOUND THEN RETURN QUERY SELECT 'absent'::TEXT,0::BIGINT,0::BIGINT; RETURN; END IF;
    SELECT * INTO STRICT namespace_row FROM cache_namespace WHERE id=namespace_id FOR UPDATE;
    SELECT * INTO STRICT generation_row FROM cache_generation WHERE id=generation_id FOR UPDATE;
    IF namespace_row.active_generation IS NOT DISTINCT FROM generation_id
       OR NOT COALESCE(generation_row.state='failed' OR (generation_row.state='retired'
          AND generation_row.readable_until<=clock_timestamp()
          AND generation_row.retired<=clock_timestamp()-make_interval(secs=>traversal_seconds::DOUBLE PRECISION)),FALSE)
       OR file_evidence_cache_generation_pinned(generation_id)
       OR EXISTS(SELECT 1 FROM workflow_cache_iteration i JOIN workflow_execution w ON w.id=i.workflow_execution
          WHERE i.generation=generation_id AND i.state='scanning'
          AND w.status NOT IN ('completed','failed','cancelled','timeout','abandoned')) THEN
        RETURN QUERY SELECT 'ineligible'::TEXT,0::BIGINT,0::BIGINT; RETURN;
    END IF;
    child_relation:=validate_cache_generation_partition(generation_id);
    PERFORM 1 FROM cache_deployment_physical_byte_usage WHERE id=1 FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'cache deployment usage is missing'; END IF;
    PERFORM 1 FROM cache_owner_physical_byte_usage WHERE owner_type=namespace_row.owner_type AND owner=namespace_row.owner FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'cache owner usage is missing'; END IF;
    SELECT * INTO STRICT usage_row FROM cache_generation_entry_usage WHERE generation=generation_id FOR UPDATE;
    EXECUTE format('DROP TABLE %s',child_relation);
    UPDATE cache_deployment_physical_byte_usage SET physical_bytes=physical_bytes-usage_row.physical_bytes
      WHERE id=1 AND physical_bytes>=usage_row.physical_bytes;
    IF NOT FOUND THEN RAISE EXCEPTION 'cache deployment usage underflow'; END IF;
    UPDATE cache_owner_physical_byte_usage SET physical_bytes=physical_bytes-usage_row.physical_bytes
      WHERE owner_type=namespace_row.owner_type AND owner=namespace_row.owner AND physical_bytes>=usage_row.physical_bytes;
    IF NOT FOUND THEN RAISE EXCEPTION 'cache owner usage underflow'; END IF;
    DELETE FROM cache_generation_entry_usage WHERE generation=generation_id;
    DELETE FROM cache_ingest_chunk WHERE generation=generation_id;
    DELETE FROM cache_generation WHERE id=generation_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'cache generation disappeared during reclamation'; END IF;
    UPDATE cache_entry_statistics_state SET partitions_dropped=partitions_dropped+1 WHERE id=TRUE;
    IF NOT FOUND THEN RAISE EXCEPTION 'cache statistics state is missing'; END IF;
    RETURN QUERY SELECT 'dropped'::TEXT,usage_row.record_count,usage_row.physical_bytes;
END;
